  const {
    themeColor,
    titleTheme,
    progressIndicator,
    disblayPagetitle,
    progressIndicatorColor,
    pullToRefresh,
    activeTabColor,
    navigationActiveColor,
    layoutTemplate,
  } = data?.app?.design || {}

  const { website } = data?.app || {}

  return (
    <Container style={styles.container}>
      <HeaderComp
        pageTitle={pageTitle}
        // setWebsiteUrl={setWebsiteUrl}
        websiteUrl={websiteUrl}
        loading={loading}
      />

      {Platform.OS == 'web' ? (
        <iframe src={websiteUrl}></iframe>
